// func decompress1x_main_loop_amd64(ctx *decompress1xContext)
// Requires: CMOV
TEXT ·decompress1x_main_loop_amd64(SB), $0-8
	MOVQ ctx+0(FP), AX

	// Preload values
	MOVBQZX 8(AX), DX
	MOVQ    32(AX), BX
	MOVQ    16(AX), SI
	MOVQ    24(AX), DI
	ADDQ    SI, DI
	MOVQ    56(AX), R8
	MOVQ    48(AX), R9
	MOVQ    (AX), CX
	MOVQ    32(CX), R10
	MOVBQZX 40(CX), R11

outer_loop:
	// Iterations allowed by the output: (limit - op) / 8
	MOVQ DI, CX
	SUBQ SI, CX
	JLE  done
	SHRQ $0x03, CX

	// Iterations allowed by the input: a refill reads the 8 bytes below the window and
	// moves it down by at most 7, so every read stays inside the stream while ip stays
	// at least 8 above ilowest.
	MOVQ    R8, R12
	SUBQ    R9, R12
	SHRQ    $0x03, R12
	CMPQ    R12, CX
	CMOVQCS R12, CX
	TESTQ   CX, CX
	JZ      done
	IMUL3Q  $0x05, CX, R12
	ADDQ    SI, R12
	PCALIGN $0x40

inner_loop:
	// symbol 0
	MOVQ    DX, CX
	MOVQ    R10, R13
	SHRQ    CL, R13
	MOVWQZX (BX)(R13*2), CX
	SHLQ    CL, R10
	ADDQ    CX, R11
	SHRQ    $0x08, CX
	MOVB    CL, (SI)

	// symbol 1
	MOVQ    DX, CX
	MOVQ    R10, R13
	SHRQ    CL, R13
	MOVWQZX (BX)(R13*2), CX
	SHLQ    CL, R10
	ADDQ    CX, R11
	SHRQ    $0x08, CX
	MOVB    CL, 1(SI)

	// symbol 2
	MOVQ    DX, CX
	MOVQ    R10, R13
	SHRQ    CL, R13
	MOVWQZX (BX)(R13*2), CX
	SHLQ    CL, R10
	ADDQ    CX, R11
	SHRQ    $0x08, CX
	MOVB    CL, 2(SI)

	// symbol 3
	MOVQ    DX, CX
	MOVQ    R10, R13
	SHRQ    CL, R13
	MOVWQZX (BX)(R13*2), CX
	SHLQ    CL, R10
	ADDQ    CX, R11
	SHRQ    $0x08, CX
	MOVB    CL, 3(SI)

	// symbol 4
	MOVQ    DX, CX
	MOVQ    R10, R13
	SHRQ    CL, R13
	MOVWQZX (BX)(R13*2), CX
	SHLQ    CL, R10
	ADDQ    CX, R11
	SHRQ    $0x08, CX
	MOVB    CL, 4(SI)

	// Refill the whole bytes consumed from below the window
	MOVQ R11, R13
	ANDQ $0x38, R13
	MOVQ -8(R8), R14
	SHRQ $0x01, R14
	ANDQ $0x07, R11
	MOVQ R13, CX
	XORQ $0x3f, CX
	SHRQ CL, R14
	MOVQ R11, CX
	SHLQ CL, R14
	ORQ  R14, R10
	SHRQ $0x03, R13
	SUBQ R13, R8
	ADDQ $0x05, SI
	CMPQ SI, R12
	JB   inner_loop
	JMP  outer_loop

done:
	// Hand the state back in the Go bit reader's own form: off = ip - in, value, bitsRead.
	MOVQ (AX), CX
	SUBQ (CX), R8
	MOVQ R8, 24(CX)
	MOVQ R10, 32(CX)
	MOVB R11, 40(CX)
	SUBQ 16(AX), SI
	MOVQ SI, 40(AX)
	RET

